//! Golden-corpus parity harness (v0.4 §3, AEOLUS_V0.4.md).
//!
//! For every corpus entry (a class string + the verbatim `tailwindcss`
//! v4.1.17 output rule for it, generated by `tools/gen_golden.mjs`), this
//! harness:
//! 1. resolves the class in aeolus (asserting ZERO warnings — the corpus
//!    covers only the supported surface),
//! 2. emits the equivalent CSS through `Resolver::to_css` (the v0.4 §1
//!    verification emitter),
//! 3. normalizes BOTH sides through the same pipeline — `var()`
//!    substitution from the golden `:root`/`@property` tables,
//!    `calc()` evaluation, rem→px, `--tw-*` machinery composition into
//!    final `box-shadow` values —
//! 4. and asserts selector, at-rule context and declaration-set equality.
//!
//! Documented normalizations (v0.4 §3.2, model choices rather than bugs):
//! * the `@media (hover: hover)` wrapper tailwind adds to `hover:`-style
//!   variants is dropped (the Probe model has no hover-capability concept),
//! * the `@media not (hover: hover)` fallback rule of `not-hover:` is
//!   skipped for the same reason,
//! * `border-*`/`outline-style: solid` declarations equal to the
//!   `--tw-*-style` @property initial value are dropped (v4 emits them
//!   mechanically with every width),
//! * unitless `line-height` ratios are multiplied by the `font-size`
//!   declared in the same rule,
//! * element-relative values (`tracking-*`, bare `leading-*`) are OUT of
//!   the corpus by construction (v0.4 §2.3): the IR resolves them at the
//!   16px base and the corpus pins px-exact semantics only.

use std::collections::{BTreeMap, HashMap};

use aeolus_core::{Resolver, TailwindTheme};

// ---------------------------------------------------------------------------
// Fixture loading (dependency-free line format, see tools/gen_golden.mjs)
// ---------------------------------------------------------------------------

struct Fixture {
    themes: HashMap<String, Vars>,
    entries: Vec<(String, String, String)>, // (theme, class, verbatim css)
}

#[derive(Default, Clone)]
struct Vars {
    root: BTreeMap<String, String>,
    props: BTreeMap<String, String>,
}

fn load_fixture() -> Fixture {
    let raw = include_str!("fixtures/golden.corpus");
    let mut themes: HashMap<String, Vars> = HashMap::new();
    let mut entries = Vec::new();
    let mut current_theme = String::new();
    let mut in_entry = false;
    let mut entry_lines: Vec<String> = Vec::new();
    let mut entry_theme = String::new();
    let mut entry_class = String::new();

    for line in raw.lines() {
        let line = line.trim_end();
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        if in_entry {
            if line.trim() == "@end" {
                entries.push((
                    std::mem::take(&mut entry_theme),
                    std::mem::take(&mut entry_class),
                    entry_lines.join("\n"),
                ));
                in_entry = false;
            } else {
                entry_lines.push(line.to_string());
            }
            continue;
        }
        if let Some(rest) = line.strip_prefix("@tailwind ") {
            assert_eq!(
                rest.trim(),
                "4.1.17",
                "corpus generated by a different tailwind"
            );
            continue;
        }
        if let Some(rest) = line.strip_prefix("@theme ") {
            current_theme = rest.trim().to_string();
            themes.entry(current_theme.clone()).or_default();
            continue;
        }
        if let Some(rest) = line.strip_prefix("@propdef ") {
            let (k, v) = rest.split_once(": ").expect("propdef");
            themes
                .entry(current_theme.clone())
                .or_default()
                .props
                .insert(k.trim().to_string(), v.trim().to_string());
            continue;
        }
        if let Some(rest) = line.strip_prefix("@entry ") {
            let (theme, class) = rest.split_once(' ').expect("entry");
            in_entry = true;
            entry_theme = theme.to_string();
            entry_class = class.to_string();
            entry_lines.clear();
            continue;
        }
        // A root variable line under @theme.
        let (k, v) = line.split_once(": ").expect("theme var line");
        themes
            .entry(current_theme.clone())
            .or_default()
            .root
            .insert(k.trim().to_string(), v.trim().to_string());
    }
    assert!(!entries.is_empty(), "empty corpus");
    Fixture { themes, entries }
}

// ---------------------------------------------------------------------------
// Golden block parsing (nesting flattening)
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
enum Node {
    Decl(String, String),
    Rule(String, Vec<Node>), // selector prelude, contains `&`
    At(String, Vec<Node>),   // @media/@container/@supports prelude
}

fn parse_block(body: &str) -> Vec<Node> {
    let mut nodes = Vec::new();
    let mut buf = String::new();
    let bytes: Vec<char> = body.chars().collect();
    let mut i = 0;
    while i < bytes.len() {
        let c = bytes[i];
        if c == '{' {
            let mut d = 1;
            let mut j = i + 1;
            while j < bytes.len() && d > 0 {
                if bytes[j] == '{' {
                    d += 1;
                }
                if bytes[j] == '}' {
                    d -= 1;
                }
                j += 1;
            }
            let inner: String = bytes[i + 1..j - 1].iter().collect();
            let sel = buf.trim().to_string();
            buf.clear();
            if sel.starts_with("@media")
                || sel.starts_with("@container")
                || sel.starts_with("@supports")
            {
                nodes.push(Node::At(sel, parse_block(&inner)));
            } else {
                nodes.push(Node::Rule(sel, parse_block(&inner)));
            }
            i = j;
            continue;
        }
        if c == ';' {
            let decl = buf.trim();
            if let Some((p, v)) = decl.split_once(':') {
                nodes.push(Node::Decl(p.trim().to_string(), v.trim().to_string()));
            }
            buf.clear();
            i += 1;
            continue;
        }
        buf.push(c);
        i += 1;
    }
    nodes
}

/// One flattened rule: (selector, media, container) + ordered decls.
#[derive(Debug, Default, Clone)]
struct FlatRule {
    selector: String,
    media: Option<String>,
    #[allow(dead_code)] // structural: kept for @container rule context
    container: Option<String>,
    decls: Vec<(String, String)>,
    /// Declared inside `@supports` — v4's modern-browser override of the
    /// plain fallback that precedes it.
    supports: bool,
}

fn flatten(
    nodes: &[Node],
    sel: &str,
    media: Option<String>,
    container: Option<String>,
    out: &mut Vec<FlatRule>,
) {
    let mut rule = FlatRule {
        selector: sel.to_string(),
        media: media.clone(),
        container: container.clone(),
        decls: Vec::new(),
        supports: false,
    };
    // Child contexts resolved at PUSH time: cascade order = the rule's own
    // declarations first, then nested blocks (last-wins for @supports).
    type ChildCtx = (Vec<Node>, String, Option<String>, Option<String>);
    let mut children: Vec<ChildCtx> = Vec::new();
    let mut supports_rules: Vec<FlatRule> = Vec::new();
    for n in nodes {
        match n {
            Node::Decl(p, v) => rule.decls.push((p.clone(), v.clone())),
            Node::Rule(s, kids) => {
                let joined = if let Some(idx) = s.find('&') {
                    format!("{}{}{}", &s[..idx], sel, &s[idx + 1..])
                } else {
                    panic!("nested selector without `&`: {s}");
                };
                children.push((kids.clone(), joined, media.clone(), container.clone()));
            }
            Node::At(prelude, kids) => {
                if prelude.contains("not (hover: hover)") {
                    continue; // documented normalization: not-hover media fallback
                }
                let cond = prelude
                    .trim_start_matches("@media")
                    .trim_start_matches("@container")
                    .trim()
                    .to_string();
                if prelude.starts_with("@container") {
                    children.push((kids.clone(), sel.to_string(), media.clone(), Some(cond)));
                } else if prelude.starts_with("@media") {
                    if cond == "(hover: hover)" || cond == "(hover: none)" {
                        // documented normalization: hover-capability wrapper
                        children.push((
                            kids.clone(),
                            sel.to_string(),
                            media.clone(),
                            container.clone(),
                        ));
                    } else {
                        let combined = match &media {
                            Some(m) => format!("{m} and {cond}"),
                            None => cond,
                        };
                        children.push((
                            kids.clone(),
                            sel.to_string(),
                            Some(combined),
                            container.clone(),
                        ));
                    }
                } else {
                    // @supports: modern-browser override — same context,
                    // replaces the plain fallback it follows.
                    let mut kid_rule = FlatRule {
                        selector: sel.to_string(),
                        media: media.clone(),
                        container: container.clone(),
                        decls: Vec::new(),
                        supports: true,
                    };
                    for k in kids {
                        if let Node::Decl(p, v) = k {
                            kid_rule.decls.push((p.clone(), v.clone()));
                        }
                    }
                    if !kid_rule.decls.is_empty() {
                        supports_rules.push(kid_rule);
                    }
                }
            }
        }
    }
    if !rule.decls.is_empty() {
        out.push(rule);
    }
    out.extend(supports_rules);
    for (kids, csel, cmedia, ccontainer) in children {
        flatten(&kids, &csel, cmedia, ccontainer, out);
    }
}

// ---------------------------------------------------------------------------
// Value normalization (shared by both sides)
// ---------------------------------------------------------------------------

fn collapse(s: &str) -> String {
    s.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn substitute_vars(value: &str, vars: &Vars, local: &BTreeMap<String, String>) -> String {
    let mut current = value.to_string();
    for _ in 0..12 {
        let Some(start) = current.find("var(") else {
            break;
        };
        // Byte-scan for the matching close paren (values are ASCII here).
        let b = current.as_bytes();
        let mut depth = 0usize;
        let mut end = start;
        for (off, &ch) in b.iter().enumerate().skip(start) {
            if ch == b'(' {
                depth += 1;
            }
            if ch == b')' {
                depth -= 1;
                if depth == 0 {
                    end = off;
                    break;
                }
            }
        }
        let inner = &current[start + 4..end];
        let (name, fallback) = match inner.split_once(',') {
            Some((n, f)) => (n.trim().to_string(), Some(f.trim().to_string())),
            None => (inner.trim().to_string(), None),
        };
        let replacement = local
            .get(&name)
            .or_else(|| vars.root.get(&name))
            .or_else(|| vars.props.get(&name))
            .or(fallback.as_ref())
            .cloned()
            .unwrap_or_default();
        let mut next = String::with_capacity(current.len());
        next.push_str(&current[..start]);
        next.push_str(&replacement);
        next.push_str(&current[end + 1..]);
        current = next;
    }
    current
}

/// Parse one length/number token: `16px`, `0.25rem` (→ px), `95%`, `45deg`,
/// `300ms`, `1`, `infinity`.
fn parse_num(tok: &str) -> Option<f32> {
    let t = tok.trim();
    let (bare, scale): (&str, f32) = if let Some(n) = t.strip_suffix("rem") {
        (n, 16.0)
    } else if let Some(n) = t.strip_suffix("px") {
        (n, 1.0)
    } else if let Some(n) = t.strip_suffix('%') {
        (n, 1.0)
    } else if let Some(n) = t.strip_suffix("deg") {
        (n, 1.0)
    } else if let Some(n) = t.strip_suffix("ms") {
        (n, 1.0)
    } else {
        (t, 1.0)
    };
    bare.parse::<f32>().ok().map(|v| v * scale)
}

fn trim_f32(v: f32) -> String {
    if v.is_infinite() {
        return if v > 0.0 {
            "infinity".into()
        } else {
            "-infinity".into()
        };
    }
    let s = format!("{:.6}", v);
    s.trim_end_matches('0').trim_end_matches('.').to_string()
}

/// Evaluate every `calc(...)` in a value, innermost-last.
fn eval_calcs(value: &str) -> String {
    let mut v = value.to_string();
    loop {
        // Find a `calc(` whose body contains no nested `calc(`.
        let mut target: Option<(usize, usize)> = None;
        let b = v.as_bytes();
        let mut i = 0;
        while i + 5 <= b.len() {
            if &b[i..i + 5] == b"calc(" {
                let mut depth = 0i32;
                let mut j = i + 4;
                let mut end = j;
                while j < b.len() {
                    if b[j] == b'(' {
                        depth += 1;
                    }
                    if b[j] == b')' {
                        depth -= 1;
                        if depth == 0 {
                            end = j;
                            break;
                        }
                    }
                    j += 1;
                }
                let inner = &v[i + 5..end];
                if !inner.contains("calc(") {
                    target = Some((i, end));
                    break;
                }
                i = end + 1;
                continue;
            }
            i += 1;
        }
        let Some((s, e)) = target else { break };
        let inner = v[s + 5..e].to_string();
        match eval_calc_expr(&inner) {
            Some((val, unit)) => {
                v = format!("{}{}{}", &v[..s], fmt_num(val, unit), &v[e + 1..]);
            }
            None => break,
        }
    }
    v
}

#[derive(Clone, Copy, Debug)]
enum Tok {
    Num(f32, &'static str),
    Op(char),
}

fn eval_calc_expr(expr: &str) -> Option<(f32, &'static str)> {
    let mut tokens: Vec<Tok> = Vec::new();
    let b = expr.as_bytes();
    let mut i = 0;
    while i < b.len() {
        let c = b[i] as char;
        if c.is_whitespace() {
            i += 1;
            continue;
        }
        if "+-*/()".contains(c) {
            tokens.push(Tok::Op(c));
            i += 1;
            continue;
        }
        if c.is_ascii_digit() || c == '.' || c == '-' || c == '+' {
            let start = i;
            while i < b.len()
                && ((b[i] as char).is_ascii_digit()
                    || b[i] == b'.'
                    || b[i] == b'-'
                    || b[i] == b'+'
                    || b[i] == b'e')
            {
                i += 1;
            }
            let num = &expr[start..i];
            let unit_start = i;
            while i < b.len() && !(b[i] as char).is_whitespace() && !"+-*/()".contains(b[i] as char)
            {
                i += 1;
            }
            let unit = &expr[unit_start..i];
            let (scale, out): (f32, &'static str) = match unit {
                "" => (1.0, ""),
                "px" => (1.0, "px"),
                "rem" => (16.0, "px"),
                "deg" => (1.0, "deg"),
                "ms" => (1.0, "ms"),
                "%" => (1.0, "%"),
                _ => return None,
            };
            let v: f32 = num.parse().ok()?;
            tokens.push(Tok::Num(v * scale, out));
            continue;
        }
        // word token (`infinity`)
        let start = i;
        while i < b.len() && !(b[i] as char).is_whitespace() && !"+-*/()".contains(b[i] as char) {
            i += 1;
        }
        match &expr[start..i] {
            "infinity" => tokens.push(Tok::Num(f32::INFINITY, "")),
            _ => return None,
        }
    }
    let mut pos = 0usize;
    let r = parse_add(&tokens, &mut pos)?;
    if pos != tokens.len() {
        return None;
    }
    Some(r)
}

fn parse_add(tokens: &[Tok], pos: &mut usize) -> Option<(f32, &'static str)> {
    let mut lhs = parse_mul(tokens, pos)?;
    while *pos < tokens.len() {
        if let Tok::Op('+') | Tok::Op('-') = tokens[*pos] {
            let op = match tokens[*pos] {
                Tok::Op(c) => c,
                _ => unreachable!(),
            };
            *pos += 1;
            let rhs = parse_mul(tokens, pos)?;
            lhs = apply_op(lhs, rhs, op)?;
        } else {
            break;
        }
    }
    Some(lhs)
}

fn parse_mul(tokens: &[Tok], pos: &mut usize) -> Option<(f32, &'static str)> {
    let mut lhs = parse_unary(tokens, pos)?;
    while *pos < tokens.len() {
        if let Tok::Op('*') | Tok::Op('/') = tokens[*pos] {
            let op = match tokens[*pos] {
                Tok::Op(c) => c,
                _ => unreachable!(),
            };
            *pos += 1;
            let rhs = parse_unary(tokens, pos)?;
            lhs = apply_op(lhs, rhs, op)?;
        } else {
            break;
        }
    }
    Some(lhs)
}

fn parse_unary(tokens: &[Tok], pos: &mut usize) -> Option<(f32, &'static str)> {
    if *pos < tokens.len() {
        if let Tok::Op('-') = tokens[*pos] {
            *pos += 1;
            let (v, u) = parse_unary(tokens, pos)?;
            return Some((-v, u));
        }
        if let Tok::Op('(') = tokens[*pos] {
            *pos += 1;
            let v = parse_add(tokens, pos)?;
            if *pos < tokens.len()
                && let Tok::Op(')') = tokens[*pos]
            {
                *pos += 1;
                return Some(v);
            }
            return None;
        }
    }
    match tokens.get(*pos)? {
        Tok::Num(v, u) => {
            let r = (*v, *u);
            *pos += 1;
            Some(r)
        }
        _ => None,
    }
}

fn apply_op(
    lhs: (f32, &'static str),
    rhs: (f32, &'static str),
    op: char,
) -> Option<(f32, &'static str)> {
    let (lv, lu) = lhs;
    let (rv, ru) = rhs;
    let unit = match op {
        '*' | '/' => {
            if lu.is_empty() {
                ru
            } else if ru.is_empty() {
                lu
            } else {
                return None;
            }
        }
        _ => {
            if lu == ru {
                lu
            } else if lu.is_empty() {
                ru
            } else if ru.is_empty() {
                lu
            } else {
                return None;
            }
        }
    };
    let v = match op {
        '+' => lv + rv,
        '-' => lv - rv,
        '*' => lv * rv,
        '/' => lv / rv,
        _ => return None,
    };
    Some((v, unit))
}

fn fmt_num(v: f32, unit: &'static str) -> String {
    format!("{}{}", trim_f32(v), unit)
}

/// Rewrite every color literal into the canonical `oklch(l c h / a)` form so
/// text-format differences (`63.7%` vs `0.637`, `#fff`, `rgb(0 0 0 / 0.1)`)
/// compare equal after parsing.
fn canonicalize_colors(value: &str) -> String {
    if !(value.contains("oklch(")
        || value.contains("oklab(")
        || value.contains("rgb(")
        || value.contains("rgba(")
        || value.contains("hsl(")
        || value.contains('#'))
    {
        return value.to_string();
    }
    let mut out = String::new();
    let b = value.as_bytes();
    let mut i = 0;
    while i < b.len() {
        let rest = &value[i..];
        let starts_color = rest.starts_with("oklch(")
            || rest.starts_with("oklab(")
            || rest.starts_with("rgb(")
            || rest.starts_with("rgba(")
            || rest.starts_with("hsl(")
            || (rest.starts_with('#')
                && rest[1..]
                    .chars()
                    .next()
                    .is_some_and(|c| c.is_ascii_hexdigit()));
        if starts_color {
            // find the token end: matching paren for functions, hex run for #
            let end = if rest.starts_with('#') {
                rest.chars().take_while(|c| c.is_ascii_hexdigit()).count() + 1
            } else {
                let mut depth = 0i32;
                let mut e = 0;
                for (off, &ch) in b[i..].iter().enumerate() {
                    if ch == b'(' {
                        depth += 1;
                    }
                    if ch == b')' {
                        depth -= 1;
                        if depth == 0 {
                            e = off + 1;
                            break;
                        }
                    }
                }
                e
            };
            let token = &rest[..end];
            match aeolus_core::Color::parse(token) {
                Ok(c) => {
                    let alpha = c.alpha;
                    let chroma = (c.a * c.a + c.b * c.b).sqrt();
                    let hue = c.b.atan2(c.a).to_degrees().rem_euclid(360.0);
                    if (alpha - 1.0).abs() < f32::EPSILON {
                        out.push_str(&format!(
                            "oklch({} {} {})",
                            trim_f32(c.l),
                            trim_f32(chroma),
                            trim_f32(hue)
                        ));
                    } else {
                        out.push_str(&format!(
                            "oklch({} {} {} / {})",
                            trim_f32(c.l),
                            trim_f32(chroma),
                            trim_f32(hue),
                            trim_f32(alpha)
                        ));
                    }
                }
                Err(_) => out.push_str(token),
            }
            i += end;
            continue;
        }
        out.push(b[i] as char);
        i += 1;
    }
    out
}

/// Evaluate `color-mix(in oklab, <color> P%, transparent)` into the mixed
/// oklch form so both sides compare numerically.
fn eval_color_mix(value: &str) -> String {
    if !value.contains("color-mix(") {
        return value.to_string();
    }
    let mut out = String::new();
    let mut rest = value;
    while let Some(start) = rest.find("color-mix(in oklab, ") {
        let tail = &rest[start..];
        if tail.find(')').is_none() {
            break;
        }
        // The inner color may itself contain parens (oklch(...)) — scan.
        let b = tail.as_bytes();
        let mut depth = 0i32;
        let mut end = start;
        for (off, &ch) in b.iter().enumerate() {
            if ch == b'(' {
                depth += 1;
            }
            if ch == b')' {
                depth -= 1;
                if depth == 0 {
                    end = start + off;
                    break;
                }
            }
        }
        let inner = &tail["color-mix(in oklab, ".len()..end - start];
        // shape: `<color> P%, transparent` — the color itself may contain
        // spaces (oklch(0.637 0.237 25.331)), so parse from the right.
        let trimmed = inner
            .trim_end()
            .strip_suffix("transparent")
            .unwrap_or(inner.trim_end());
        let trimmed = trimmed.trim_end();
        let mut it = trimmed.rsplitn(2, ' ');
        let pct_tok = it.next().unwrap_or("").trim().trim_end_matches(',');
        let color_tok = it.next().unwrap_or("").trim();
        if let Ok(c) = aeolus_core::Color::parse(color_tok)
            && let Ok(pct) = pct_tok.trim_end_matches('%').parse::<f32>()
        {
            let mixed = c.mix_with_transparent(pct);
            out.push_str(&rest[..start]);
            out.push_str(&format!(
                "oklch({} {} {} / {})",
                trim_f32(mixed.l),
                trim_f32((mixed.a * mixed.a + mixed.b * mixed.b).sqrt()),
                trim_f32(mixed.b.atan2(mixed.a).to_degrees().rem_euclid(360.0)),
                trim_f32(mixed.alpha)
            ));
            rest = &tail[end - start + 1..];
            continue;
        }
        // Not evaluatable — keep verbatim.
        out.push_str(&rest[..end + 1]);
        rest = &tail[end - start + 1..];
    }
    out.push_str(rest);
    out
}

/// Full value normalization: vars → calc → color-mix → colors → collapse.
fn normalize_value(value: &str, vars: &Vars, local: &BTreeMap<String, String>) -> String {
    let v = substitute_vars(value, vars, local);
    let v = eval_calcs(&v);
    let v = eval_color_mix(&v);
    let v = canonicalize_colors(&v);
    collapse(&v)
}

/// Documented normalization: a unitless `line-height` ratio is multiplied by
/// the `font-size` declared in the same rule (both sides run through this).
fn scale_unitless_line_height(decls: &mut [(String, String)]) {
    let font_px = decls
        .iter()
        .find(|(p, _)| p == "font-size")
        .and_then(|(_, v)| parse_num(v));
    let Some(font_px) = font_px else { return };
    for (p, v) in decls.iter_mut() {
        if p == "line-height"
            && let Some(ratio) = parse_num(v)
            && !v.contains("px")
            && !v.contains('%')
        {
            *v = format!("{}px", trim_f32(ratio * font_px));
        }
    }
}

// ---------------------------------------------------------------------------
// Comparison
// ---------------------------------------------------------------------------

fn top_level_commas(s: &str) -> Vec<String> {
    let mut parts = Vec::new();
    let mut depth = 0i32;
    let mut cur = String::new();
    for c in s.chars() {
        match c {
            '(' => {
                depth += 1;
                cur.push(c);
            }
            ')' => {
                depth -= 1;
                cur.push(c);
            }
            ',' if depth == 0 => {
                parts.push(cur.trim().to_string());
                cur.clear();
            }
            _ => cur.push(c),
        }
    }
    if !cur.trim().is_empty() {
        parts.push(cur.trim().to_string());
    }
    parts
}

fn value_eq(a: &str, b: &str) -> bool {
    let a = collapse(a);
    let b = collapse(b);
    if a == b {
        return true;
    }
    // Colors (approximate Oklab equality).
    if let (Ok(ca), Ok(cb)) = (aeolus_core::Color::parse(&a), aeolus_core::Color::parse(&b))
        && ca == cb
    {
        return true;
    }
    // Comma-separated layers (box-shadow): layer-wise.
    let (la, lb) = (top_level_commas(&a), top_level_commas(&b));
    if la.len() == lb.len() && la.len() > 1 {
        return la.iter().zip(lb.iter()).all(|(x, y)| token_eq(x, y));
    }
    token_eq(&a, &b)
}

fn token_eq(a: &str, b: &str) -> bool {
    let ta: Vec<&str> = a.split_whitespace().collect();
    let tb: Vec<&str> = b.split_whitespace().collect();
    if ta.len() == tb.len() && ta.len() > 1 {
        return ta.iter().zip(tb.iter()).all(|(x, y)| token_eq(x, y));
    }
    if let (Some(na), Some(nb)) = (parse_num(a), parse_num(b)) {
        return (na - nb).abs() <= 1e-4_f32.max(na.abs() * 1e-4);
    }
    if let (Some(ra), Some(rb)) = (ratio_of(a), ratio_of(b)) {
        return (ra - rb).abs() <= 1e-4_f32.max(ra.abs() * 1e-4);
    }
    a == b
}

fn ratio_of(s: &str) -> Option<f32> {
    let (x, y) = s.split_once('/')?;
    let (x, y) = (x.trim().parse::<f32>().ok()?, y.trim().parse::<f32>().ok()?);
    Some(x / y)
}

// ---------------------------------------------------------------------------
// The parity test
// ---------------------------------------------------------------------------

fn theme_for(name: &str) -> TailwindTheme {
    match name {
        "shadcn" => aeolus_core::shadcn_default().unwrap(),
        _ => TailwindTheme::default(),
    }
}

/// Declarations the harness drops: mechanical v4 noise.
/// * `border-*`/`outline-style: solid` = the @property initial emitted with
///   every width;
/// * custom-property assignments (`--tw-*`, `--tw-duration`, …) — consumed
///   by the substitution pass, never compared directly.
fn is_dropped(prop: &str, value: &str) -> bool {
    if prop.starts_with("--") {
        return true;
    }
    let style_ctx =
        (prop.starts_with("border") || prop.starts_with("outline")) && prop.ends_with("-style");
    style_ctx && value == "solid"
}

#[test]
fn golden_corpus_parity() {
    let fx = load_fixture();
    let mut failures: Vec<String> = Vec::new();
    let mut checked = 0usize;

    for (theme, class, css) in &fx.entries {
        let vars = &fx.themes[theme];
        let t = theme_for(theme);
        let resolver = Resolver::new(&t);

        let out = match resolver.to_css(class) {
            Ok(out) => out,
            Err(e) => {
                failures.push(format!("{theme}:{class} — resolve error {e:?}"));
                continue;
            }
        };
        if !out.warnings.is_empty() {
            failures.push(format!("{theme}:{class} — warnings {:#?}", out.warnings));
            continue;
        }

        // Flatten the golden block.
        let first = css.find('{').expect("golden rule");
        let sel = css[..first].trim();
        let body = &css[first + 1..css.rfind('}').expect("closing")];
        let mut golden_rules = Vec::new();
        flatten(&parse_block(body), sel, None, None, &mut golden_rules);

        // Normalize golden: substitute vars + compose the --tw machinery.
        let mut normalized: Vec<(String, String, BTreeMap<String, String>)> = Vec::new();
        for r in &golden_rules {
            let local: BTreeMap<String, String> = r
                .decls
                .iter()
                .filter(|(p, _)| p.starts_with("--"))
                .map(|(p, v)| (p.clone(), v.clone()))
                .collect();
            let mut decls: Vec<(String, String)> = Vec::new();
            for (p, v) in &r.decls {
                if p.starts_with("--") {
                    continue;
                }
                let nv = compose_box_shadow(p, v, vars, &local);
                if is_dropped(p, &nv) || nv.is_empty() {
                    continue;
                }
                decls.push((p.to_string(), nv));
            }
            scale_unitless_line_height(&mut decls);
            let entry = (
                r.selector.clone(),
                r.media.clone().unwrap_or_default(),
                decls.into_iter().collect::<BTreeMap<_, _>>(),
            );
            if r.supports {
                // modern-browser override: replace same-prop decls of the
                // preceding plain rule (same selector + context)
                if let Some(prev) = normalized
                    .iter_mut()
                    .rev()
                    .find(|(s2, m2, _)| *s2 == entry.0 && *m2 == entry.1)
                {
                    for (p, v) in entry.2 {
                        prev.2.insert(p, v);
                    }
                }
            } else {
                normalized.push(entry);
            }
        }

        // Normalize ours the same way (vars no-op; calc eval matters).
        let mut our_rules: Vec<(String, String, BTreeMap<String, String>)> = Vec::new();
        for rule in &out.rules {
            let mut decls: Vec<(String, String)> = Vec::new();
            for (p, v) in &rule.declarations {
                let nv = normalize_value(v, vars, &BTreeMap::new());
                if is_dropped(p, &nv) {
                    continue;
                }
                decls.push((p.to_string(), nv));
            }
            scale_unitless_line_height(&mut decls);
            our_rules.push((
                rule.selector.clone(),
                rule.media.clone().unwrap_or_default(),
                decls.into_iter().collect(),
            ));
        }

        checked += 1;
        if normalized.is_empty() && our_rules.iter().all(|(_, _, d)| d.is_empty()) {
            continue; // vacuous on both sides (e.g. ring color without width)
        }
        // Match rule-by-rule on (selector, media).
        for (sel, media, decls) in &normalized {
            let found = our_rules.iter().find(|(s, m, _)| s == sel && m == media);
            match found {
                None => failures.push(format!(
                    "{theme}:{class} — missing rule sel={sel:?} media={media:?}\n  golden decls: {decls:?}\n  ours: {our_rules:?}"
                )),
                Some((_, _, ours)) => {
                    for (p, v) in decls {
                        match ours.get(p) {
                            Some(ov) if value_eq(v, ov) => {}
                            Some(ov) => failures.push(format!(
                                "{theme}:{class} [{sel} {media}] {p}: golden {v:?} vs ours {ov:?}"
                            )),
                            None => failures.push(format!(
                                "{theme}:{class} [{sel} {media}] {p}: golden {v:?} — OURS MISSING (have {ours:?})"
                            )),
                        }
                    }
                    for (p, v) in ours.iter() {
                        if !decls.contains_key(p) {
                            failures.push(format!(
                                "{theme}:{class} [{sel} {media}] extra decl {p}: {v:?} (golden {decls:?})"
                            ));
                        }
                    }
                }
            }
        }
        for (sel, media, decls) in &our_rules {
            if decls.is_empty() {
                continue;
            }
            if !normalized.iter().any(|(s, m, _)| s == sel && m == media) {
                failures.push(format!(
                    "{theme}:{class} — EXTRA rule sel={sel:?} media={media:?} decls={decls:?} (golden {normalized:?})"
                ));
            }
        }
    }

    assert!(checked >= 150, "corpus shrank: {checked}");
    if !failures.is_empty() {
        panic!(
            "{} parity failures (of {checked} entries):\n{}",
            failures.len(),
            failures.join("\n")
        );
    }
}

/// Compose the `--tw-*` shadow/ring machinery: for the var-list form of
/// `box-shadow`, resolve each layer through the var map (BEFORE the outer
/// substitution pass) and drop zero transparent layers.
fn compose_box_shadow(
    prop: &str,
    value: &str,
    vars: &Vars,
    local: &BTreeMap<String, String>,
) -> String {
    if prop != "box-shadow" {
        return normalize_value(value, vars, local);
    }
    if !value.contains("var(") {
        return normalize_value(value, vars, local);
    }
    let layers = top_level_commas(value);
    let mut kept: Vec<String> = Vec::new();
    for l in layers {
        let resolved = normalize_value(&l, vars, local);
        if is_zero_transparent_layer(&resolved) {
            continue;
        }
        kept.push(resolved);
    }
    collapse(&kept.join(", "))
}

fn is_zero_transparent_layer(layer: &str) -> bool {
    let toks: Vec<&str> = layer.split_whitespace().collect();
    if toks.len() < 3 {
        return false;
    }
    let color_tok = toks[toks.len() - 1];
    let transparent = color_tok == "#0000"
        || color_tok == "transparent"
        || color_tok.ends_with("/ 0)")
        || color_tok.ends_with("/ 0%)");
    if !transparent {
        return false;
    }
    let len_toks = &toks[..toks.len() - 1];
    let all_lens = len_toks.iter().all(|t| parse_num(t).is_some());
    all_lens
        && len_toks
            .iter()
            .filter_map(|t| parse_num(t))
            .all(|v| v == 0.0)
}
